SELECT A.FINPROD_ID AS code, A.FINPROD_NAME AS name, A.FINPROD_ID AS hidCode, A.FINPROD_ABBR AS shortName FROM FIN_PRODUCT A WHERE A.FINPROD_TYPE = #{finprodType}
AND A.PROFIT_TYPE IN
#{item}
AND ( A.FINPROD_ID like concat_ws('','%',#{param},'%') OR A.FINPROD_NAME like concat_ws('','%',#{param},'%') )
